use parseapi::Country;
#[test] fn country_actual_name_family_and_detail(){let c:Country=serde_json::from_str(include_str!("fixtures/country-corrected.json")).unwrap();assert_eq!(c.name_full.as_deref(),Some("United States of America"));assert_eq!(c.full_name,c.name_full);assert_eq!(c.demonym.as_deref(),Some("American"));assert_eq!(c.numeric,Some(840));let d=c.deep.unwrap();assert_eq!(d.demonym,None);assert_eq!(d.full_name,None);assert_eq!(d.gdp_per_capita_usd,Some(90026.52));assert_eq!(d.elevation_average,Some(760.0));assert!(d.population.is_some()&&d.area.is_some());}
#[test] fn country_legacy_names_and_explicit_null(){for text in [r#"{"country":"US","name":"US","continent":"NA","languages":[],"name_full":"Full"}"#,r#"{"country":"US","name":"US","continent":"NA","languages":[],"full_name":"Full"}"#]{let c:Country=serde_json::from_str(text).unwrap();assert_eq!(c.name_full.as_deref(),Some("Full"));assert_eq!(c.full_name,c.name_full);}let c:Country=serde_json::from_str(r#"{"country":"US","name":"US","continent":"NA","languages":[],"name_full":null,"full_name":"Legacy","deep":{"full_name":"Earlier","demonym":"Earlier"}}"#).unwrap();assert_eq!(c.name_full,None);assert_eq!(c.full_name,None);let d=c.deep.unwrap();assert_eq!(d.full_name.as_deref(),Some("Earlier"));assert_eq!(d.demonym.as_deref(),Some("Earlier"));}
#[test] fn country_actual_antarctica_null_array(){let c:Country=serde_json::from_str(include_str!("fixtures/country-aq.json")).unwrap();assert!(c.languages.is_empty());assert!(c.currency.is_none()&&c.currency_name.is_none()&&c.currency_symbol.is_none());assert_eq!(c.name_full.as_deref(),Some("Antarctica"));assert_eq!(c.deep.unwrap().population,Some(0));}

#[test] fn country_nested_objects_and_flag(){
 let us:Country=serde_json::from_str(include_str!("fixtures/country-corrected.json")).unwrap();assert_eq!(us.flag.as_deref(),Some("🇺🇸"));assert_eq!(us.emoji,us.flag);let cap=us.capital.as_ref().unwrap();assert_eq!(cap.name.as_deref(),Some("Washington, D.C."));assert_eq!(cap.latitude,Some(38.89));assert_eq!(cap.longitude,Some(-77.05));let tax=us.deep.as_ref().unwrap().tax.as_ref().unwrap();assert!(tax.name.is_none()&&tax.rate.is_none());
 let de:Country=serde_json::from_str(include_str!("fixtures/country-de.json")).unwrap();let detail=de.deep.unwrap();assert!(detail.tax_id_format.is_none()&&detail.tax_id_regex.is_none());let tax=detail.tax.unwrap();assert_eq!(tax.name.as_deref(),Some("VAT"));assert_eq!(tax.rate,Some(19.0));
}
#[test] fn country_legacy_groups_preserve_zero_and_canonical_null(){
 let legacy:Country=serde_json::from_str(r#"{"country":"XX","name":"Example","continent":"NA","emoji":"old","capital":null,"capital_lat":0,"capital_lon":0,"deep":{"tax":null,"tax_rate":0,"tax_id_format":"9","tax_id_regex":"^9$","population":0,"area":0}}"#).unwrap();assert_eq!(legacy.flag.as_deref(),Some("old"));let cap=legacy.capital.unwrap();assert_eq!(cap.name,None);assert_eq!(cap.latitude,Some(0.0));let detail=legacy.deep.unwrap();assert_eq!(detail.tax_id_format.as_deref(),Some("9"));let tax=detail.tax.unwrap();assert_eq!(tax.name,None);assert_eq!(tax.rate,Some(0.0));
 let current:Country=serde_json::from_str(r#"{"country":"XX","name":"Example","continent":"NA","flag":null,"emoji":"old","capital":{"name":null,"latitude":null,"longitude":0},"capital_lat":9,"capital_lon":9,"deep":{"tax":{"name":null,"rate":null},"tax_rate":99,"tax_id_format":"stale"}}"#).unwrap();assert_eq!(current.flag,None);let cap=current.capital.unwrap();assert_eq!(cap.name,None);assert_eq!(cap.latitude,None);assert_eq!(cap.longitude,Some(0.0));let detail=current.deep.unwrap();assert!(detail.tax_id_format.is_none());assert_eq!(detail.tax.unwrap().rate,None);
}
#[test] fn country_compact_and_locked(){
 for text in [r#"{"country":"US","name":"US","flag":"🇺🇸"}"#,r#"{"country":"US","name":"US","emoji":"🇺🇸"}"#]{let item:parseapi::ContinentCountryItem=serde_json::from_str(text).unwrap();assert_eq!(item.flag.as_deref(),Some("🇺🇸"));assert_eq!(item.emoji,item.flag);}
 let item:parseapi::ContinentCountryItem=serde_json::from_str(r#"{"country":"US","name":"US","flag":null,"emoji":"old"}"#).unwrap();assert_eq!(item.flag,None);
 let core:Country=serde_json::from_str(r#"{"country":"US","name":"US","continent":"NA"}"#).unwrap();assert!(core.deep.is_none());let locked:Country=serde_json::from_str(r#"{"country":"US","name":"US","continent":"NA","deep":{}}"#).unwrap();assert!(locked.deep.unwrap().tax.is_none());
}
